// src/pages/Profile.jsx
import { useState } from "react";
import C from "../constants/colors";
import S from "../utils/storage";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import Btn from "../components/ui/Btn";
import Input from "../components/ui/Input";
import LanguageSwitcher, { LANGUAGES } from "../components/ui/LanguageSwitcher";


const TN_DISTRICTS = [
  "Ariyalur","Chengalpattu","Chennai","Coimbatore","Cuddalore","Dharmapuri",
  "Dindigul","Erode","Kallakurichi","Kancheepuram","Kanyakumari","Karur",
  "Krishnagiri","Madurai","Mayiladuthurai","Nagapattinam","Namakkal","Nilgiris",
  "Perambalur","Pudukkottai","Ramanathapuram","Ranipet","Salem","Sivaganga",
  "Tenkasi","Thanjavur","Theni","Thoothukudi","Tirunelveli","Tirupattur",
  "Tiruchirappalli","Tiruppur","Tiruvallur","Tiruvannamalai","Tiruvarur",
  "Vellore","Viluppuram","Virudhunagar",
];

export default function Profile({ user, onLogout, setLang, lang, t }) {
  const [edit, setEdit] = useState(false);
  const [saved, setSaved] = useState(false);
  const [form, setForm] = useState({
    name:     user?.name     || "",
    district: user?.district || "",
    landSize: user?.landSize || "",
  });

  const f = (k) => (e) => setForm(p => ({ ...p, [k]: e.target.value }));

  const save = () => {
    const users   = S.get("users") || [];
    const idx     = users.findIndex(u => u.id === user.id);
    const updated = { ...user, ...form, landSize: parseFloat(form.landSize) || 0 };
    if (idx >= 0) {
      users[idx] = updated;
      S.set("users", users);
      S.set("current_user", updated);
    }
    setSaved(true);
    setEdit(false);
    setTimeout(() => setSaved(false), 2000);
  };

  // ── Translation strings ───────────────────────────────────────────────────
  const TX = {
    title:        t("profile.title")         || "My Profile",
    editProfile:  t("profile.editProfile")   || "Edit Profile",
    saveChanges:  t("profile.saveChanges")   || "Save Changes",
    cancel:       t("cancel")                || "Cancel",
    logout:       t("profile.logout")        || "Logout",
    farmerInfo:   t("profile.farmerInfo")    || "Farmer Information",
    farmDetails:  t("profile.farmDetails")   || "Farm Details",
    myCrops:      t("profile.myCrops")       || "My Crops",
    diseaseHist:  t("profile.diseaseHistory")|| "Disease History",
    noHistory:    t("profile.noHistory")     || "No disease scans yet",
    noCrops:      "No crops registered.",
    nameLabel:    t("auth.name")             || "Full Name",
    phoneLabel:   t("auth.phone")            || "Mobile",
    districtLabel:t("auth.district")         || "District",
    stateLabel:   "State",
    landLabel:    t("auth.farmSize")         || "Land Size",
    langLabel:    t("profile.language")      || "App Language",
    changeLang:   t("profile.changeLang")    || "Change Language",
    appSettings:  t("profile.appSettings")   || "App Settings",
    joined:       "Joined",
    acres:        t("common.acres")          || "acres",
    notSet:       "Not set",
    savedMsg:     "✅ Profile saved!",
  };

  const langLabel = { en: "English", ta: "தமிழ்", hi: "हिंदी" };

  // Safe user fields
  const crops         = Array.isArray(user?.crops)          ? user.crops          : [];
  const diseaseHistory= Array.isArray(user?.diseaseHistory) ? user.diseaseHistory : [];
  const joinedDate    = user?.createdAt
    ? new Date(user.createdAt).toLocaleDateString("en-IN")
    : "—";

  return (
    <div style={{ padding: 22, maxWidth: 620 }}>
      <h1 style={{ fontSize: 21, fontWeight: 600, color: C.text, margin: "0 0 16px" }}>
        👤 {TX.title}
      </h1>

      {saved && (
        <div style={{ background: "#f0fff4", color: "#1a5a30", padding: "10px 14px", borderRadius: 8, fontSize: 13, marginBottom: 12, border: "1px solid #b2dfdb" }}>
          {TX.savedMsg}
        </div>
      )}

      {/* ── Profile Card ─────────────────────────────────────────────────── */}
      <Card style={{ marginBottom: 14 }}>
        {/* Avatar */}
        <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 16 }}>
          <div style={{
            width: 60, height: 60, borderRadius: "50%",
            background: C.bg2, color: "#fff",
            display: "flex", alignItems: "center", justifyContent: "center",
            fontSize: 22, fontWeight: 700,
          }}>
            {(user?.name || "?").slice(0, 2).toUpperCase()}
          </div>
          <div>
            <div style={{ fontSize: 18, fontWeight: 600, color: C.text }}>{user?.name}</div>
            <div style={{ fontSize: 13, color: C.muted }}>
              {user?.phone} • {TX.joined} {joinedDate}
            </div>
            <Badge>{user?.district}, TN</Badge>
          </div>
        </div>

        {edit ? (
          <>
            <div style={{ fontSize: 11, color: C.muted, fontWeight: 600, marginBottom: 10, textTransform: "uppercase", letterSpacing: "0.05em" }}>
              {TX.farmerInfo}
            </div>
            <Input label={TX.nameLabel}     value={form.name}     onChange={f("name")} />
            <Input label={TX.districtLabel} value={form.district} onChange={f("district")} options={TN_DISTRICTS} />
            <Input label={`${TX.landLabel} (${TX.acres})`} type="number" value={form.landSize} onChange={f("landSize")} placeholder="e.g. 3.5" />
            <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
              <Btn onClick={save}>✅ {TX.saveChanges}</Btn>
              <Btn variant="ghost" onClick={() => setEdit(false)}>{TX.cancel}</Btn>
            </div>
          </>
        ) : (
          <>
            {[
              [TX.phoneLabel,    user?.phone                                        ],
              [TX.districtLabel, user?.district                                     ],
              [TX.stateLabel,    "Tamil Nadu"                                       ],
              [TX.landLabel,     `${user?.landSize || TX.notSet} ${TX.acres}`       ],
              [TX.langLabel,     langLabel[lang] || "English"                       ],
            ].map(([label, value]) => (
              <div key={label} style={{
                display: "flex", justifyContent: "space-between",
                padding: "8px 0", borderBottom: `1px solid ${C.border}`, fontSize: 13,
              }}>
                <span style={{ color: C.muted }}>{label}</span>
                <span style={{ color: C.text, fontWeight: 500 }}>{value}</span>
              </div>
            ))}
            <div style={{ marginTop: 14, display: "flex", gap: 8, flexWrap: "wrap" }}>
              <Btn onClick={() => setEdit(true)} variant="outline">✏️ {TX.editProfile}</Btn>
              <Btn onClick={onLogout} variant="danger">🚪 {TX.logout}</Btn>
            </div>
          </>
        )}
      </Card>

      {/* ── Language Settings ─────────────────────────────────────────────── */}
      <Card style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 12 }}>
          🌐 {TX.appSettings}
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontSize: 13, fontWeight: 500, color: C.text }}>{TX.changeLang}</div>
            <div style={{ fontSize: 11.5, color: C.muted, marginTop: 2 }}>English / தமிழ் / हिंदी</div>
          </div>
          {/* ✅ Uses standalone LanguageSwitcher — no circular import */}
          <LanguageSwitcher lang={lang} setLang={setLang} />
        </div>
      </Card>

      {/* ── My Crops ──────────────────────────────────────────────────────── */}
      <Card style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 10 }}>
          🌾 {TX.myCrops} ({crops.length})
        </div>
        {crops.length > 0
          ? <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
              {crops.map(c => <Badge key={c}>{c}</Badge>)}
            </div>
          : <div style={{ fontSize: 13, color: C.muted }}>{TX.noCrops}</div>
        }
      </Card>

      {/* ── Disease History ───────────────────────────────────────────────── */}
      <Card>
        <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 10 }}>
          🔬 {TX.diseaseHist}
        </div>
        {diseaseHistory.length === 0
          ? <div style={{ fontSize: 13, color: C.muted }}>{TX.noHistory}</div>
          : diseaseHistory.slice(0, 5).map((d, i) => (
              <div key={i} style={{
                display: "flex", justifyContent: "space-between",
                padding: "6px 0",
                borderBottom: i < Math.min(diseaseHistory.length, 5) - 1 ? `1px solid ${C.border}` : "none",
                fontSize: 12.5,
              }}>
                <span style={{ color: C.text }}>{d.crop} — {d.disease}</span>
                <span style={{ color: C.muted }}>{d.date}</span>
              </div>
            ))
        }
      </Card>
    </div>
  );
}
